input.command:
cat > /workspace/harness/lib.mjs <<'EOF'
import { spawnSync } from 'node:child_process';
import { readFileSync } from 'node:fs';
export const EXE = '/workspace/dataset/test6_executable';
export const JS  = '/output/test6.mjs';
export const SENT = 'ZqSENTINELqZ';
const SENT_OUT = '<p>' + SENT + '</p>\n';

export function loadCases(file) {
  return readFileSync(file, 'utf8').split('\n')
    .filter(l => l.trim() !== '')
    .map(l => { const v = JSON.parse(l); return typeof v === 'string' ? { label: v, text: v } : v; });
}
// Run one markdown text through a converter, returning {html, rc, stderr}
function run(cmd, argv, text) {
  const r = spawnSync(cmd, [...argv, '--a', text, '--b', SENT], { encoding: 'utf8', maxBuffer: 1 << 26 });
  if (r.status !== 0) return { html: null, rc: r.status, stderr: r.stderr };
  const i = r.stdout.lastIndexOf(SENT_OUT);
  return { html: i >= 0 ? r.stdout.slice(0, i) : r.stdout, rc: 0, stderr: r.stderr };
}
export const py = (text) => run(EXE, [], text);
export const js = (text) => run('node', [JS], text);
// Raw invocation with arbitrary argv (for argparse-fidelity tests)
export function rawPy(argv) { const r = spawnSync(EXE, argv, { encoding: 'utf8' }); return { out: r.stdout, err: r.stderr, rc: r.status }; }
export function rawJs(argv) { const r = spawnSync('node', [JS, ...argv], { encoding: 'utf8' }); return { out: r.stdout, err: r.stderr, rc: r.status }; }
EOF
cat > /workspace/harness/probe.mjs <<'EOF'
import { loadCases, py } from './lib.mjs';
for (const c of loadCases(process.argv[2])) {
  const r = py(c.text);
  console.log('### ' + JSON.stringify(c.label));
  console.log('IN  ' + JSON.stringify(c.text));
  if (r.rc !== 0) console.log('RC  ' + r.rc + '  ERR ' + JSON.stringify(r.stderr));
  else console.log('OUT ' + JSON.stringify(r.html));
}
EOF
cat > /workspace/harness/diff.mjs <<'EOF'
import { loadCases, py, js } from './lib.mjs';
let pass = 0; const fails = [];
for (const c of loadCases(process.argv[2])) {
  const a = py(c.text), b = js(c.text);
  const same = a.rc === b.rc && a.html === b.html;
  if (same) pass++; else fails.push({ c, a, b });
}
for (const f of fails) {
  console.log('--- MISMATCH ' + JSON.stringify(f.c.label));
  console.log('  IN  ' + JSON.stringify(f.c.text));
  console.log('  PY  ' + (f.a.rc ? 'RC=' + f.a.rc + ' ' + JSON.stringify(f.a.stderr) : JSON.stringify(f.a.html)));
  console.log('  JS  ' + (f.b.rc ? 'RC=' + f.b.rc + ' ' + JSON.stringify(f.b.stderr) : JSON.stringify(f.b.html)));
}
console.log(`\n=== ${pass} pass / ${fails.length} FAIL (of ${pass + fails.length}) ===`);
process.exit(fails.length ? 1 : 0);
EOF
node /workspace/harness/probe.mjs /workspace/harness/c1.jsonl 2>&1 | head -8
echo "OK harness ready"; time (/workspace/dataset/test6_executable --a x --b y >/dev/null)

cat > /workspace/harness/wordprobe.mjs <<'EOF'
// Empirically determine which code points Python's re \w matches, by exploiting
// SMART_EMPHASIS's (?<!\w) lookbehind:  "q" + CHAR + "_z_"  =>  <em>z</em> only when CHAR is NOT \w.
import { spawnSync } from 'node:child_process';
const EXE = '/workspace/dataset/test6_executable';
const SKIP = new Set();
for (let i = 0; i < 0x80; i++) SKIP.add(i);              // ASCII handled from knowledge
for (let i = 0xD800; i <= 0xDFFF; i++) SKIP.add(i);      // lone surrogates
const ranges = JSON.parse(process.argv[2]);              // [[lo,hi],...]
const cps = [];
for (const [lo, hi] of ranges) for (let cp = lo; cp <= hi; cp++) if (!SKIP.has(cp)) cps.push(cp);
const CHUNK = 4000;
const word = [], nonword = [], weird = [];
for (let i = 0; i < cps.length; i += CHUNK) {
  const batch = cps.slice(i, i + CHUNK);
  const doc = batch.map(cp => 'q' + String.fromCodePoint(cp) + '_z_').join('\n');
  const r = spawnSync(EXE, ['--a', doc, '--b', 'S'], { encoding: 'utf8', maxBuffer: 1 << 28 });
  if (r.status !== 0) { console.error('FAIL batch at ' + i + ': ' + r.stderr); process.exit(1); }
  let body = r.stdout.slice(0, r.stdout.lastIndexOf('<p>S</p>\n'));
  body = body.trim();
  if (body.startsWith('<p>')) body = body.slice(3);
  if (body.endsWith('</p>')) body = body.slice(0, -4);
  const lines = body.split('\n');
  if (lines.length !== batch.length) { console.error(`LINE COUNT MISMATCH at ${i}: ${lines.length} vs ${batch.length}`); process.exit(1); }
  for (let j = 0; j < batch.length; j++) {
    const cp = batch[j], ch = String.fromCodePoint(cp), L = lines[j];
    if (L === 'q' + ch + '<em>z</em>') nonword.push(cp);
    else if (L === 'q' + ch + '_z_') word.push(cp);
    else weird.push([cp, L]);
  }
}
console.log(JSON.stringify({ word: pack(word), nonword: pack(nonword), weird }));
function pack(list) { const out = []; for (const cp of list) { const last = out[out.length - 1]; if (last && last[1] === cp - 1) last[1] = cp; else out.push([cp, cp]); } return out; }
EOF
node /workspace/harness/wordprobe.mjs '[[128,600]]' > /tmp/wp_test.json 2>/tmp/wp_err.txt; echo "rc=$?"; head -c 1500 /tmp/wp_test.json; echo; echo "ERR:"; head -c 500 /tmp/wp_err.txt

