/**
 * Shared constants and small helpers used across the converter.
 *
 * The two control characters below act as sentinels that cannot occur in the
 * user's document (they are stripped from the input during normalization), so
 * they can safely delimit internal placeholders.
 */

export const STX = '';
export const ETX = '';

export const INLINE_PLACEHOLDER_PREFIX = STX + 'klzzwxh:';
export const INLINE_PLACEHOLDER_SUFFIX = ETX;

export const HTML_PLACEHOLDER_PREFIX = STX + 'wzxhzdk:';
export const HTML_PLACEHOLDER_SUFFIX = ETX;

/** Stand-in for a literal ampersand that must survive attribute escaping. */
export const AMP_SUBSTITUTE = STX + 'amp' + ETX;

export const TAB_LENGTH = 4;

export function inlinePlaceholder(id) {
  return INLINE_PLACEHOLDER_PREFIX + id + INLINE_PLACEHOLDER_SUFFIX;
}

export function htmlPlaceholder(id) {
  return HTML_PLACEHOLDER_PREFIX + id + HTML_PLACEHOLDER_SUFFIX;
}

/**
 * Elements that may not be wrapped in a `<p>`, plus elements whose contents
 * the converter must leave alone.
 */
export const BLOCK_LEVEL_ELEMENTS = new Set([
  'address', 'article', 'aside', 'blockquote', 'details', 'div', 'dl',
  'fieldset', 'figcaption', 'figure', 'footer', 'form', 'h1', 'h2', 'h3',
  'h4', 'h5', 'h6', 'header', 'hgroup', 'hr', 'main', 'menu', 'nav', 'ol',
  'p', 'pre', 'section', 'table', 'ul',
  'canvas', 'colgroup', 'dd', 'body', 'dt', 'group', 'iframe', 'li', 'legend',
  'math', 'map', 'noscript', 'output', 'object', 'option', 'progress', 'script',
  'style', 'summary', 'tbody', 'td', 'textarea', 'tfoot', 'th', 'thead', 'tr',
  'video',
]);

export function isBlockLevel(tag) {
  if (typeof tag !== 'string' || tag.length === 0) return false;
  // A leading '!' marks a comment/declaration node; those are never block level.
  if (tag.charCodeAt(0) === 33 /* ! */) return false;
  return BLOCK_LEVEL_ELEMENTS.has(tag.toLowerCase());
}

/** Elements serialized as self-closing in XHTML output. */
export const HTML_EMPTY = new Set([
  'area', 'base', 'basefont', 'br', 'col', 'embed', 'frame', 'hr', 'img',
  'input', 'isindex', 'link', 'meta', 'param', 'source', 'track', 'wbr',
]);

/**
 * A string marked as "atomic" is never re-scanned for inline markup.
 * Implemented as a wrapper object rather than a String subclass so identity
 * survives being stored in and read back out of the tree.
 */
export class AtomicString {
  constructor(value) {
    this.value = value;
  }
  toString() {
    return this.value;
  }
}

export function isAtomic(value) {
  return value instanceof AtomicString;
}

/** Read a text slot that may hold either a plain string or an AtomicString. */
export function textOf(value) {
  if (value === null || value === undefined) return null;
  return value instanceof AtomicString ? value.value : value;
}

/** Holds raw HTML removed from the document, keyed by insertion order. */
export class HtmlStash {
  constructor() {
    this.rawHtmlBlocks = [];
    this.tagCounter = 0;
    this.tagData = [];
  }

  /** Store a fragment and return the placeholder that stands in for it. */
  store(html) {
    const id = this.rawHtmlBlocks.length;
    this.rawHtmlBlocks.push(html);
    return htmlPlaceholder(id);
  }

  reset() {
    this.rawHtmlBlocks = [];
  }

  get(index) {
    return this.rawHtmlBlocks[index];
  }

  get length() {
    return this.rawHtmlBlocks.length;
  }
}

/**
 * An ordered, priority-sorted collection of named processors.
 * Higher priority runs first; ties keep insertion order.
 */
export class Registry {
  constructor() {
    this._items = [];
  }

  register(item, name, priority) {
    const existing = this._items.findIndex((entry) => entry.name === name);
    if (existing !== -1) this._items.splice(existing, 1);
    this._items.push({ item, name, priority });
    this._items.sort((a, b) => b.priority - a.priority);
    return this;
  }

  deregister(name) {
    const index = this._items.findIndex((entry) => entry.name === name);
    if (index !== -1) this._items.splice(index, 1);
    return this;
  }

  get(name) {
    const entry = this._items.find((e) => e.name === name);
    return entry ? entry.item : undefined;
  }

  /** Iterate the processors in priority order. */
  *[Symbol.iterator]() {
    for (const entry of this._items) yield entry.item;
  }

  get names() {
    return this._items.map((e) => e.name);
  }
}

