/**
 * A minimal element tree, mirroring the shape the block and inline processors
 * expect: every node carries `text` (content before its first child) and
 * `tail` (content after the node's closing tag).
 */

import { AtomicString, textOf } from './util.mjs';

/** Sentinel tags for nodes that are not real elements. */
export const COMMENT = '#comment';
export const PROCESSING_INSTRUCTION = '#pi';

export class Element {
  constructor(tag, attrib) {
    this.tag = tag;
    this.attrib = new Map();
    this.text = null;
    this.tail = null;
    this.children = [];
    if (attrib) for (const [k, v] of Object.entries(attrib)) this.attrib.set(k, v);
  }

  set(key, value) {
    this.attrib.set(key, value);
  }

  get(key, fallback = null) {
    return this.attrib.has(key) ? this.attrib.get(key) : fallback;
  }

  /** Attribute pairs ordered by name, matching the reference serializer. */
  items() {
    const pairs = [...this.attrib.entries()];
    pairs.sort((a, b) => compareCodePoints(a[0], b[0]));
    return pairs;
  }

  append(child) {
    this.children.push(child);
    return child;
  }

  insert(index, child) {
    this.children.splice(index, 0, child);
    return child;
  }

  remove(child) {
    const index = this.children.indexOf(child);
    if (index !== -1) this.children.splice(index, 1);
  }

  extend(children) {
    for (const child of children) this.children.push(child);
  }

  indexOf(child) {
    return this.children.indexOf(child);
  }

  get length() {
    return this.children.length;
  }

  /** Depth-first iteration over this element and all descendants. */
  *iter() {
    yield this;
    for (const child of this.children) yield* child.iter();
  }

  /** Plain text of `this.text`, unwrapping an atomic marker if present. */
  textString() {
    return textOf(this.text);
  }

  tailString() {
    return textOf(this.tail);
  }

  get textIsAtomic() {
    return this.text instanceof AtomicString;
  }

  get tailIsAtomic() {
    return this.tail instanceof AtomicString;
  }
}

