/**
 * XHTML serialization of the element tree.
 *
 * Mirrors the reference serializer's escaping rules exactly:
 *  - character data escapes `&`, `<`, `>` (in that order)
 *  - attribute values additionally escape `"` and encode newlines as `&#10;`
 *    while leaving `'` untouched
 *  - attributes are emitted sorted by name
 *  - empty HTML elements are written self-closing
 *  - `<script>` and `<style>` bodies are written verbatim
 */

import { HTML_EMPTY } from './util.mjs';
import { COMMENT, PROCESSING_INSTRUCTION } from './etree.mjs';

export function escapeCdata(text) {
  let out = text;
  if (out.indexOf('&') !== -1) out = out.split('&').join('&amp;');
  if (out.indexOf('<') !== -1) out = out.split('<').join('&lt;');
  if (out.indexOf('>') !== -1) out = out.split('>').join('&gt;');
  return out;
}

export function escapeAttrib(text) {
  let out = text;
  if (out.indexOf('&') !== -1) out = out.split('&').join('&amp;');
  if (out.indexOf('<') !== -1) out = out.split('<').join('&lt;');
  if (out.indexOf('>') !== -1) out = out.split('>').join('&gt;');
  if (out.indexOf('"') !== -1) out = out.split('"').join('&quot;');
  if (out.indexOf('\n') !== -1) out = out.split('\n').join('&#10;');
  return out;
}

const VERBATIM_BODY = new Set(['script', 'style']);

function write(parts, element) {
  const tag = element.tag;
  const text = element.textString();

  if (tag === COMMENT) {
    parts.push('<!--' + (text === null ? '' : text) + '-->');
  } else if (tag === PROCESSING_INSTRUCTION) {
    parts.push('<?' + (text === null ? '' : text) + '?>');
  } else if (tag === null) {
    // A tagless wrapper contributes only its content.
    if (text) parts.push(escapeCdata(text));
    for (const child of element.children) write(parts, child);
  } else {
    parts.push('<' + tag);
    for (const [name, value] of element.items()) {
      parts.push(' ' + name + '="' + escapeAttrib(String(value)) + '"');
    }
    const lower = tag.toLowerCase();
    if (HTML_EMPTY.has(lower)) {
      parts.push(' />');
    } else {
      parts.push('>');
      if (text) parts.push(VERBATIM_BODY.has(lower) ? text : escapeCdata(text));
      for (const child of element.children) write(parts, child);
      parts.push('</' + tag + '>');
    }
  }

  const tail = element.tailString();
  if (tail) parts.push(escapeCdata(tail));
}

export function toXhtml(element) {
  const parts = [];
  write(parts, element);
  return parts.join('');
}

