  if (index < 0 || index >= text.length) return false;
  const code = text.charCodeAt(index);
  if (code >= 0xd800 && code <= 0xdbff && index + 1 < text.length) {
    const next = text.charCodeAt(index + 1);
    if (next >= 0xdc00 && next <= 0xdfff) {
      return isWordCodePoint((code - 0xd800) * 0x400 + (next - 0xdc00) + 0x10000);
    }
  }
  if (code >= 0xdc00 && code <= 0xdfff && index > 0) {
    const prev = text.charCodeAt(index - 1);
    // Second half of a pair already accounted for by the first half.
    if (prev >= 0xd800 && prev <= 0xdbff) {
      return isWordCodePoint((prev - 0xd800) * 0x400 + (code - 0xdc00) + 0x10000);
    }
  }
  return isWordCodePoint(code);
}

/** Word-character test for the character ending at `index` (exclusive). */
export function isWordBefore(text, index) {
  return index > 0 && isWordAt(text, index - 1);
}

export function isDigitCode(code) {
  return code >= 0x30 && code <= 0x39;
}

export function isDigitAt(text, index) {
  if (index < 0 || index >= text.length) return false;
  return isDigitCode(text.charCodeAt(index));
}

export function isHexAt(text, index) {
  if (index < 0 || index >= text.length) return false;
  const code = text.charCodeAt(index);
  return (
    (code >= 0x30 && code <= 0x39) ||
    (code >= 0x41 && code <= 0x46) ||
    (code >= 0x61 && code <= 0x66)
  );
}

export function isAsciiLetterAt(text, index) {
  if (index < 0 || index >= text.length) return false;
  const code = text.charCodeAt(index);
  return (code >= 0x41 && code <= 0x5a) || (code >= 0x61 && code <= 0x7a);
}

export function isAsciiAlnumAt(text, index) {
  return isAsciiLetterAt(text, index) || isDigitAt(text, index);
}

/** Python's `str.strip()` with no argument. */
export function strip(text) {
  return rstrip(lstrip(text));
}

export function lstrip(text) {
  let start = 0;
  while (start < text.length && SPACE_CODE_POINTS.has(text.charCodeAt(start))) start++;
  return start === 0 ? text : text.slice(start);
}

export function rstrip(text) {
  let end = text.length;
  while (end > 0 && SPACE_CODE_POINTS.has(text.charCodeAt(end - 1))) end--;
  return end === text.length ? text : text.slice(0, end);
}

/** Python's `str.strip(chars)` / `lstrip(chars)` / `rstrip(chars)`. */
export function stripChars(text, chars) {
  return rstripChars(lstripChars(text, chars), chars);
}

export function lstripChars(text, chars) {
  let start = 0;
  while (start < text.length && chars.indexOf(text[start]) !== -1) start++;
  return text.slice(start);
}

export function rstripChars(text, chars) {
  let end = text.length;
  while (end > 0 && chars.indexOf(text[end - 1]) !== -1) end--;
  return text.slice(0, end);
}

/** True when the string is empty or contains only whitespace. */
export function isBlank(text) {
  for (let i = 0; i < text.length; i++) {
    if (!SPACE_CODE_POINTS.has(text.charCodeAt(i))) return false;
  }
  return true;
}

/**
 * Python's `str.expandtabs(tabsize)`: column-aware, with the column counter
 * reset by `\n` and `\r`.
 */
export function expandTabs(text, tabSize = 4) {
  if (text.indexOf('\t') === -1) return text;
  const out = [];
  let column = 0;
  for (let i = 0; i < text.length; i++) {
    const ch = text[i];
    if (ch === '\t') {
      if (tabSize > 0) {
        const width = tabSize - (column % tabSize);
        out.push(' '.repeat(width));
        column += width;
      }
    } else {
      out.push(ch);
      if (ch === '\n' || ch === '\r') column = 0;
      else column += 1;
    }
  }
  return out.join('');
}

/** Count the leading spaces of a line. */
export function countLeadingSpaces(text) {
  let n = 0;
  while (n < text.length && text.charCodeAt(n) === 0x20) n++;
  return n;
}

/** True when `text` contains `needle` starting exactly at `index`. */
export function matchesAt(text, index, needle) {
  if (index < 0 || index + needle.length > text.length) return false;
  for (let i = 0; i < needle.length; i++) {
    if (text.charCodeAt(index + i) !== needle.charCodeAt(i)) return false;
  }
  return true;
}

/** Length of the run of `ch` starting at `index`. */
export function runLength(text, index, ch) {
  const code = ch.charCodeAt(0);
  let n = 0;
  while (index + n < text.length && text.charCodeAt(index + n) === code) n++;
  return n;
}

