/**
 * Recognition of HTML character-reference syntax.
 *
 * Two grammars are needed and they differ:
 *
 *  - `entityLengthAt` accepts a *complete* reference (`&name;`, `&#65;`,
 *    `&#x41;`). It decides whether an `&` may be emitted literally instead of
 *    being escaped to `&amp;`, and whether an inline reference is preserved.
 *  - `matchCharRef` mirrors the tokenizer's numeric-reference rule, where the
 *    trailing semicolon is optional but *some* non-hex terminator must follow.
 */

import { isAsciiAlnumAt, isAsciiLetterAt, isDigitAt, isHexAt } from './chars.mjs';

/**
 * Length of a complete character reference starting at `index` (which must be
 * an `&`), or -1 when there is none.
 *
 * Grammar: `&` ( `#` digit+ | `#` [xX] hexdigit+ | alnum+ ) `;`
 */
export function entityLengthAt(text, index) {
  if (text.charCodeAt(index) !== 0x26 /* & */) return -1;
  let i = index + 1;
  if (text.charCodeAt(i) === 0x23 /* # */) {
    i += 1;
    const code = text.charCodeAt(i);
    if (code === 0x78 /* x */ || code === 0x58 /* X */) {
      i += 1;
      const start = i;
      while (isHexAt(text, i)) i++;
      if (i === start) return -1;
    } else {
      const start = i;
      while (isDigitAt(text, i)) i++;
      if (i === start) return -1;
    }
  } else {
    const start = i;
    while (isAsciiAlnumAt(text, i)) i++;
    if (i === start) return -1;
  }
  if (text.charCodeAt(i) !== 0x3b /* ; */) return -1;
  return i + 1 - index;
}

/** True when a complete character reference starts at `index`. */
export function isEntityAt(text, index) {
  return entityLengthAt(text, index) !== -1;
}

/**
 * The tokenizer's numeric character reference: `&#` followed by decimal digits
 * or `x`/`X` and hex digits, then a character that is not a hex digit.
 *
 * Returns `{ name, end, terminator }` or null. `end` is the index of the
 * terminating character (which the caller consumes only when it is `;`).
 */
export function matchCharRef(text, index) {
  if (text.charCodeAt(index) !== 0x26 || text.charCodeAt(index + 1) !== 0x23) return null;
  let i = index + 2;
  const code = text.charCodeAt(i);
  if (isDigitAt(text, i)) {
    while (isDigitAt(text, i)) i++;
  } else if (code === 0x78 || code === 0x58) {
    i += 1;
    const start = i;
    while (isHexAt(text, i)) i++;
    if (i === start) return null;
  } else {
    return null;
  }
  // A terminator must exist and must not itself be a hex digit; because digits
  // are hex digits, backtracking the run could never rescue a failure here.
  if (i >= text.length || isHexAt(text, i)) return null;
  return { name: text.slice(index + 2, i), end: i, terminator: text[i] };
}

/**
 * The tokenizer's named character reference: `&`, a letter, then letters,
 * digits, `-` or `.`, and a mandatory `;`.
 *
 * Returns `{ name, end }` (end is past the semicolon) or null.
 */
export function matchEntityRef(text, index) {
  if (text.charCodeAt(index) !== 0x26) return null;
  let i = index + 1;
  if (!isAsciiLetterAt(text, i)) return null;
  i += 1;
  while (i < text.length) {
    const code = text.charCodeAt(i);
    if (isAsciiAlnumAt(text, i) || code === 0x2d /* - */ || code === 0x2e /* . */) i++;
    else break;
  }
  if (text.charCodeAt(i) !== 0x3b) return null;
  return { name: text.slice(index + 1, i), end: i + 1 };
}

