/**
 * A tokenizer for HTML markup, close enough to Python's `html.parser` that the
 * raw-HTML extraction it drives behaves identically — including its tolerance
 * for malformed markup and its treatment of unterminated constructs.
 *
 * The scanner walks the document once, calling handler methods on a delegate.
 * `parser.pos` is the index of the construct currently being reported, which
 * the delegate needs in order to decide whether a tag begins a line.
 */

import { isAsciiLetterAt, isSpaceAt, isHexAt, matchesAt, strip } from './chars.mjs';
import { matchCharRef, matchEntityRef } from './entityref.mjs';

/** Elements whose content is raw text terminated only by their end tag. */
const CDATA_CONTENT_ELEMENTS = new Set(['script', 'style']);

/** Characters excluded from a tag name. */
function isTagNameChar(text, i) {
  if (i >= text.length) return false;
  const code = text.charCodeAt(i);
  return !(
    code === 0x09 || code === 0x0a || code === 0x0d || code === 0x0c ||
    code === 0x20 || code === 0x2f /* / */ || code === 0x3e /* > */ || code === 0x00
  );
}

/** Whitespace as recognized by a regular expression's `\s`. */
function isWs(text, i) {
  return isSpaceAt(text, i);
}

function skipWs(text, i) {
  while (isWs(text, i)) i++;
  return i;
}

export class HtmlTokenizer {
  constructor(delegate) {
    this.delegate = delegate;
    this.rawdata = '';
    this.pos = 0;
    this.lineStart = 0;
    this.cdataElem = null;
  }

  /** Column of the construct currently being reported. */
  get offset() {
    return this.pos - this.lineStart;
  }

  setCdataMode(elem) {
    this.cdataElem = elem.toLowerCase();
  }

  clearCdataMode() {
    this.cdataElem = null;
  }

  /** Advance the reported position, tracking the start of the current line. */
  _advance(to) {
    const data = this.rawdata;
    for (let i = this.pos; i < to; i++) {
      if (data.charCodeAt(i) === 0x0a) this.lineStart = i + 1;
    }
    this.pos = to;
  }

  parse(source) {
    this.rawdata = source;
    this.pos = 0;
    this.lineStart = 0;
    const data = source;
    const n = data.length;
    let i = 0;

    while (i < n) {
      // Find the next construct of interest.
      let j;
      if (this.cdataElem !== null) {
        j = this._findCdataEnd(i);
        if (j < 0) j = n;
      } else {
        j = this._findInteresting(i);
        if (j < 0) j = n;
      }
      if (i < j) {
        this._advance(i);
        this.delegate.handleData(data.slice(i, j));
        i = j;
      }
      this._advance(i);
      if (i >= n) break;

      let k;
      if (data.charCodeAt(i) === 0x3c /* < */) {
        if (isAsciiLetterAt(data, i + 1)) k = this._parseStartTag(i);
        else if (matchesAt(data, i, '</')) k = this._parseEndTag(i);
        else if (matchesAt(data, i, '<!--')) k = this._parseComment(i);
        else if (matchesAt(data, i, '<?')) k = this._parsePi(i);
        else if (matchesAt(data, i, '<!')) k = this._parseHtmlDeclaration(i);
        else {
          this.delegate.handleData('<');
          k = i + 1;
        }
        if (k < 0) {
          // Unterminated construct: emit up to the next '>' or '<' as text.
          k = data.indexOf('>', i + 1);
          if (k < 0) {
            k = data.indexOf('<', i + 1);
            if (k < 0) k = i + 1;
          } else {
            k += 1;
          }
          this.delegate.handleData(data.slice(i, k));
        }
        i = k;
        this._advance(i);
        continue;
      }

      // An '&': numeric references are recognized with an optional semicolon,
      // named references only with one.
      if (matchesAt(data, i, '&#')) {
        const ref = matchCharRef(data, i);
        if (ref) {
          this.delegate.handleCharref(ref.name);
          i = ref.terminator === ';' ? ref.end + 1 : ref.end;
          this._advance(i);
          continue;
        }
        if (data.indexOf(';', i) !== -1) {
          // Give up on this reference by consuming just the "&#".
          this.delegate.handleData(data.slice(i, i + 2));
          i += 2;
          this._advance(i);
          continue;
        }
        // Nothing can complete it: the remainder is plain text and scanning stops.
        this.delegate.handleData(data.slice(i));
        this._advance(n);
        return;
      }

      const named = matchEntityRef(data, i);
      if (named) {
        this.delegate.handleEntityref(named.name);
        i = named.end;
        this._advance(i);
        continue;
      }
      this.delegate.handleData('&');
      i += 1;
      this._advance(i);
