  _findInteresting(from) {
    const data = this.rawdata;
    for (let i = from; i < data.length; i++) {
      const code = data.charCodeAt(i);
      if (code === 0x3c || code === 0x26) return i;
    }
    return -1;
  }

  /** Inside `<script>`/`<style>`, only the matching end tag is of interest. */
  _findCdataEnd(from) {
    const data = this.rawdata;
    const elem = this.cdataElem;
    for (let i = from; i < data.length; i++) {
      if (data.charCodeAt(i) !== 0x3c || data.charCodeAt(i + 1) !== 0x2f) continue;
      let j = skipWs(data, i + 2);
      if (data.slice(j, j + elem.length).toLowerCase() === elem) return i;
