  /**
   * Locate the end of a start tag's attribute list, mirroring the tolerant
   * grammar: tag name, then `[\s/]*` and any number of attributes, then `\s*`.
   */
  _locateStartTagEnd(i) {
    const data = this.rawdata;
    let j = i + 2; // '<' plus the first letter of the name
    while (isTagNameChar(data, j)) j++;
    while (isWs(data, j) || data.charCodeAt(j) === 0x2f) j++;
