   * One attribute: a name (preceded by a quote, whitespace or slash), an
   * optional `= value`, then trailing whitespace or a slash not closing the tag.
   * Returns the position after it, or -1.
   */
  _matchAttribute(k) {
    const data = this.rawdata;
    if (k === 0) return -1;
    const prev = data.charCodeAt(k - 1);
    const prevOk =
      prev === 0x27 || prev === 0x22 || prev === 0x2f || isSpaceAt(data, k - 1);
    if (!prevOk) return -1;

    let i = k;
    // First name character: not whitespace, '/' or '>'.
    if (i >= data.length) return -1;
    let code = data.charCodeAt(i);
    if (isWs(data, i) || code === 0x2f || code === 0x3e) return -1;
