    // Optional value, introduced by one or more '=' signs.
    const beforeValue = i;
    let j = skipWs(data, i);
    if (data.charCodeAt(j) === 0x3d) {
      while (data.charCodeAt(j) === 0x3d) j++;
      j = skipWs(data, j);
      const quote = data.charCodeAt(j);
      let ok = true;
      if (quote === 0x27 || quote === 0x22) {
        const close = data.indexOf(String.fromCharCode(quote), j + 1);
        if (close === -1) ok = false; // unterminated: treat the value as absent
