      } else {
        while (j < data.length && !isWs(data, j) && data.charCodeAt(j) !== 0x3e) j++;
      }
      if (ok) {
        // Any number of trailing commas.
        for (;;) {
          const save = j;
          const afterWs = skipWs(data, j);
          if (data.charCodeAt(afterWs) === 0x2c) j = afterWs + 1;
          else {
            j = save;
            break;
          }
        }
        i = j;
      } else {
        i = beforeValue;
      }
    } else {
      i = beforeValue;
    }

    while (i < data.length) {
      if (isWs(data, i)) i++;
      else if (data.charCodeAt(i) === 0x2f && data.charCodeAt(i + 1) !== 0x3e) i++;
      else break;
    }
    return i;
  }

  _checkForWholeStartTag(i) {
    const data = this.rawdata;
    const j = this._locateStartTagEnd(i);
    const next = j < data.length ? data[j] : '';
    if (next === '>') return j + 1;
    if (next === '/') {
      if (matchesAt(data, j, '/>')) return j + 2;
      return -1;
    }
    if (next === '') return -1;
    if (next === '=' || isAsciiLetterAt(data, j)) return -1;
