  }

  _parseStartTag(i) {
    const data = this.rawdata;
    const endpos = this._checkForWholeStartTag(i);
    if (endpos < 0) return endpos;

    // Tag name, then whitespace or slashes that do not close the tag.
    let k = i + 1;
    const nameStart = k;
    k += 1;
    while (isTagNameChar(data, k)) k++;
    const tag = data.slice(nameStart, k).toLowerCase();
    while (k < endpos) {
      if (isWs(data, k)) k++;
      else if (data.charCodeAt(k) === 0x2f && data.charCodeAt(k + 1) !== 0x3e) k++;
      else break;
    }
    while (k < endpos) {
      const next = this._matchAttribute(k);
      if (next === -1 || next === k) break;
      k = next;
    }

    const end = strip(data.slice(k, endpos));
    if (end !== '>' && end !== '/>') {
      this.delegate.handleData(data.slice(i, endpos));
