  }

  // ------------------------------------------------------------------ end tag

  _parseEndTag(i) {
    const data = this.rawdata;
    const gt = data.indexOf('>', i + 1);
    if (gt === -1) return -1;
    let gtpos = gt + 1;

    // The strict form: '</', optional space, a name, optional space, '>'.
    const strict = this._matchEndTagFind(i);
    if (strict === null) {
      if (this.cdataElem !== null) {
        this.delegate.handleData(data.slice(i, gtpos));
        return gtpos;
      }
      let j = i + 2;
      if (!isAsciiLetterAt(data, j)) {
        if (matchesAt(data, i, '</>')) return i + 3;
        return this._parseBogusComment(i);
      }
      const nameStart = j;
      j += 1;
      while (isTagNameChar(data, j)) j++;
      const tagname = data.slice(nameStart, j).toLowerCase();
      while (isWs(data, j) || (data.charCodeAt(j) === 0x2f && data.charCodeAt(j + 1) !== 0x3e)) j++;
      gtpos = data.indexOf('>', j);
      this.delegate.handleEndtag(tagname, data.slice(i, gtpos + 1));
      return gtpos + 1;
    }

    const elem = strict.tag;
    if (this.cdataElem !== null && elem !== this.cdataElem) {
      this.delegate.handleData(data.slice(i, gtpos));
      return gtpos;
    }
    this.delegate.handleEndtag(elem, data.slice(i, strict.end));
    this.clearCdataMode();
    return strict.end;
  }

  /** `</\s*([a-zA-Z][-.a-zA-Z0-9:_]*)\s*>` anchored at `i`. */
  _matchEndTagFind(i) {
    const data = this.rawdata;
    if (!matchesAt(data, i, '</')) return null;
    let j = skipWs(data, i + 2);
    if (!isAsciiLetterAt(data, j)) return null;
    const nameStart = j;
    j += 1;
    while (j < data.length) {
      const code = data.charCodeAt(j);
      const ok =
        isAsciiLetterAt(data, j) ||
        (code >= 0x30 && code <= 0x39) ||
        code === 0x2d || code === 0x2e || code === 0x3a || code === 0x5f;
      if (!ok) break;
      j += 1;
    }
    const name = data.slice(nameStart, j);
    j = skipWs(data, j);
    if (data.charCodeAt(j) !== 0x3e) return null;
    return { tag: name.toLowerCase(), end: j + 1 };
  }

  // ------------------------------------------------- comments and declarations

  _parseComment(i) {
    const data = this.rawdata;
    // Closing sequence is '--' followed by optional whitespace and '>'.
    for (let j = i + 4; j < data.length; j++) {
      if (data.charCodeAt(j) !== 0x2d || data.charCodeAt(j + 1) !== 0x2d) continue;
      const k = skipWs(data, j + 2);
      if (data.charCodeAt(k) === 0x3e) {
        this.delegate.handleComment(data.slice(i + 4, j));
        return k + 1;
      }
    }
    return -1;
  }

  _parseBogusComment(i) {
    const data = this.rawdata;
    const pos = data.indexOf('>', i + 2);
    if (pos === -1) return -1;
    this.delegate.handleComment(data.slice(i + 2, pos));
    return pos + 1;
  }

  _parsePi(i) {
    const data = this.rawdata;
    const j = data.indexOf('>', i + 2);
    if (j === -1) return -1;
    this.delegate.handlePi(data.slice(i + 2, j));
    return j + 1;
  }

  _parseHtmlDeclaration(i) {
    const data = this.rawdata;
    if (matchesAt(data, i, '<!--')) return this._parseComment(i);
    if (matchesAt(data, i, '<![')) return this._parseMarkedSection(i);
    if (data.slice(i, i + 9).toLowerCase() === '<!doctype') {
      const gt = data.indexOf('>', i + 9);
      if (gt === -1) return -1;
      this.delegate.handleDecl(data.slice(i + 2, gt));
      return gt + 1;
    }
    return this._parseBogusComment(i);
  }

  _parseMarkedSection(i) {
    const data = this.rawdata;
    let j = i + 3;
    const nameStart = j;
    while (j < data.length && (isAsciiLetterAt(data, j) || isHexAt(data, j))) j++;
