      // Standard ']]>' terminator, allowing whitespace between the parts.
      for (let p = i + 3; p < data.length; p++) {
        if (data.charCodeAt(p) !== 0x5d) continue;
        let q = skipWs(data, p + 1);
        if (data.charCodeAt(q) !== 0x5d) continue;
        q = skipWs(data, q + 1);
        if (data.charCodeAt(q) !== 0x3e) continue;
        this.delegate.handleUnknownDecl(data.slice(i + 3, p));
        return q + 1;
      }
      return -1;
    }
    if (['if', 'else', 'endif'].includes(sectName)) {
      for (let p = i + 3; p < data.length; p++) {
        if (data.charCodeAt(p) !== 0x5d) continue;
        const q = skipWs(data, p + 1);
        if (data.charCodeAt(q) !== 0x3e) continue;
        this.delegate.handleUnknownDecl(data.slice(i + 3, p));
        return q + 1;
      }
      return -1;
    }
    return this._parseBogusComment(i);
  }
}

