/**
 * A tokenizer for HTML markup, close enough to Python's `html.parser` that the
 * raw-HTML extraction it drives behaves identically — including its tolerance
 * for malformed markup and its treatment of unterminated constructs.
 *
 * The scanner walks the document once, calling handler methods on a delegate.
 * `parser.pos` is the index of the construct currently being reported, which
 * the delegate needs in order to decide whether a tag begins a line.
 */

import { isAsciiLetterAt, isSpaceAt, isHexAt, matchesAt, strip } from './chars.mjs';
import { matchCharRef, matchEntityRef } from './entityref.mjs';

/** Elements whose content is raw text terminated only by their end tag. */
const CDATA_CONTENT_ELEMENTS = new Set(['script', 'style']);

/** Characters excluded from a tag name. */
function isTagNameChar(text, i) {
  if (i >= text.length) return false;
  const code = text.charCodeAt(i);
  return !(
    code === 0x09 || code === 0x0a || code === 0x0d || code === 0x0c ||
    code === 0x20 || code === 0x2f /* / */ || code === 0x3e /* > */ || code === 0x00
  );
}

/** Whitespace as recognized by a regular expression's `\s`. */
function isWs(text, i) {
  return isSpaceAt(text, i);
}

function skipWs(text, i) {
  while (isWs(text, i)) i++;
  return i;
}

export class HtmlTokenizer {
  constructor(delegate) {
    this.delegate = delegate;
    this.rawdata = '';
    this.pos = 0;
    this.lineStart = 0;
    this.cdataElem = null;
  }

  /** Column of the construct currently being reported. */
  get offset() {
    return this.pos - this.lineStart;
  }

  setCdataMode(elem) {
    this.cdataElem = elem.toLowerCase();
  }

  clearCdataMode() {
    this.cdataElem = null;
  }

  /** Advance the reported position, tracking the start of the current line. */
  _advance(to) {
    const data = this.rawdata;
    for (let i = this.pos; i < to; i++) {
      if (data.charCodeAt(i) === 0x0a) this.lineStart = i + 1;
    }
    this.pos = to;
  }

  parse(source) {
    this.rawdata = source;
    this.pos = 0;
    this.lineStart = 0;
    const data = source;
    const n = data.length;
    let i = 0;

    while (i < n) {
      // Find the next construct of interest.
      let j;
      if (this.cdataElem !== null) {
        j = this._findCdataEnd(i);
        if (j < 0) j = n;
      } else {
        j = this._findInteresting(i);
        if (j < 0) j = n;
      }
      if (i < j) {
        this._advance(i);
        this.delegate.handleData(data.slice(i, j));
        i = j;
      }
      this._advance(i);
      if (i >= n) break;

      let k;
      if (data.charCodeAt(i) === 0x3c /* < */) {
        if (isAsciiLetterAt(data, i + 1)) k = this._parseStartTag(i);
        else if (matchesAt(data, i, '</')) k = this._parseEndTag(i);
        else if (matchesAt(data, i, '<!--')) k = this._parseComment(i);
        else if (matchesAt(data, i, '<?')) k = this._parsePi(i);
        else if (matchesAt(data, i, '<!')) k = this._parseHtmlDeclaration(i);
        else {
          this.delegate.handleData('<');
          k = i + 1;
        }
        if (k < 0) {
          // Unterminated construct: emit up to the next '>' or '<' as text.
          k = data.indexOf('>', i + 1);
          if (k < 0) {
            k = data.indexOf('<', i + 1);
            if (k < 0) k = i + 1;
          } else {
            k += 1;
          }
          this.delegate.handleData(data.slice(i, k));
        }
        i = k;
        this._advance(i);
        continue;
      }

      // An '&': numeric references are recognized with an optional semicolon,
      // named references only with one.
      if (matchesAt(data, i, '&#')) {
        const ref = matchCharRef(data, i);
        if (ref) {
          this.delegate.handleCharref(ref.name);
          i = ref.terminator === ';' ? ref.end + 1 : ref.end;
          this._advance(i);
          continue;
        }
        if (data.indexOf(';', i) !== -1) {
          // Give up on this reference by consuming just the "&#".
          this.delegate.handleData(data.slice(i, i + 2));
          i += 2;
          this._advance(i);
          continue;
        }
        // Nothing can complete it: the remainder is plain text and scanning stops.
        this.delegate.handleData(data.slice(i));
        this._advance(n);
        return;
      }

      const named = matchEntityRef(data, i);
      if (named) {
        this.delegate.handleEntityref(named.name);
        i = named.end;
        this._advance(i);
        continue;
      }
      this.delegate.handleData('&');
      i += 1;
      this._advance(i);
    }
  }

  _findInteresting(from) {
    const data = this.rawdata;
    for (let i = from; i < data.length; i++) {
      const code = data.charCodeAt(i);
      if (code === 0x3c || code === 0x26) return i;
    }
    return -1;
  }

  /** Inside `<script>`/`<style>`, only the matching end tag is of interest. */
  _findCdataEnd(from) {
    const data = this.rawdata;
    const elem = this.cdataElem;
    for (let i = from; i < data.length; i++) {
      if (data.charCodeAt(i) !== 0x3c || data.charCodeAt(i + 1) !== 0x2f) continue;
      let j = skipWs(data, i + 2);
      if (data.slice(j, j + elem.length).toLowerCase() === elem) return i;
    }
    return -1;
  }

  // ---------------------------------------------------------------- start tag

  /**
   * Locate the end of a start tag's attribute list, mirroring the tolerant
   * grammar: tag name, then `[\s/]*` and any number of attributes, then `\s*`.
   */
  _locateStartTagEnd(i) {
    const data = this.rawdata;
    let j = i + 2; // '<' plus the first letter of the name
    while (isTagNameChar(data, j)) j++;
    while (isWs(data, j) || data.charCodeAt(j) === 0x2f) j++;
    for (;;) {
      const next = this._matchAttribute(j);
      if (next === -1) break;
      j = next;
    }
    return skipWs(data, j);
  }

  /**
   * One attribute: a name (preceded by a quote, whitespace or slash), an
   * optional `= value`, then trailing whitespace or a slash not closing the tag.
   * Returns the position after it, or -1.
   */
  _matchAttribute(k) {
    const data = this.rawdata;
    if (k === 0) return -1;
    const prev = data.charCodeAt(k - 1);
    const prevOk =
      prev === 0x27 || prev === 0x22 || prev === 0x2f || isSpaceAt(data, k - 1);
    if (!prevOk) return -1;

    let i = k;
    // First name character: not whitespace, '/' or '>'.
    if (i >= data.length) return -1;
    let code = data.charCodeAt(i);
    if (isWs(data, i) || code === 0x2f || code === 0x3e) return -1;
    i += 1;
    while (i < data.length) {
      code = data.charCodeAt(i);
      if (isWs(data, i) || code === 0x2f || code === 0x3d || code === 0x3e) break;
      i += 1;
    }

    // Optional value, introduced by one or more '=' signs.
    const beforeValue = i;
    let j = skipWs(data, i);
    if (data.charCodeAt(j) === 0x3d) {
      while (data.charCodeAt(j) === 0x3d) j++;
      j = skipWs(data, j);
      const quote = data.charCodeAt(j);
      let ok = true;
      if (quote === 0x27 || quote === 0x22) {
        const close = data.indexOf(String.fromCharCode(quote), j + 1);
        if (close === -1) ok = false; // unterminated: treat the value as absent
        else j = close + 1;
      } else {
        while (j < data.length && !isWs(data, j) && data.charCodeAt(j) !== 0x3e) j++;
      }
      if (ok) {
        // Any number of trailing commas.
        for (;;) {
          const save = j;
          const afterWs = skipWs(data, j);
          if (data.charCodeAt(afterWs) === 0x2c) j = afterWs + 1;
          else {
            j = save;
            break;
          }
        }
        i = j;
      } else {
        i = beforeValue;
      }
    } else {
      i = beforeValue;
    }

    while (i < data.length) {
      if (isWs(data, i)) i++;
      else if (data.charCodeAt(i) === 0x2f && data.charCodeAt(i + 1) !== 0x3e) i++;
      else break;
    }
    return i;
  }

  _checkForWholeStartTag(i) {
    const data = this.rawdata;
    const j = this._locateStartTagEnd(i);
    const next = j < data.length ? data[j] : '';
    if (next === '>') return j + 1;
    if (next === '/') {
      if (matchesAt(data, j, '/>')) return j + 2;
      return -1;
    }
    if (next === '') return -1;
    if (next === '=' || isAsciiLetterAt(data, j)) return -1;
    return j > i ? j : i + 1;
  }

  _parseStartTag(i) {
    const data = this.rawdata;
    const endpos = this._checkForWholeStartTag(i);
    if (endpos < 0) return endpos;

    // Tag name, then whitespace or slashes that do not close the tag.
    let k = i + 1;
    const nameStart = k;
    k += 1;
    while (isTagNameChar(data, k)) k++;
    const tag = data.slice(nameStart, k).toLowerCase();
    while (k < endpos) {
      if (isWs(data, k)) k++;
      else if (data.charCodeAt(k) === 0x2f && data.charCodeAt(k + 1) !== 0x3e) k++;
      else break;
    }
    while (k < endpos) {
      const next = this._matchAttribute(k);
      if (next === -1 || next === k) break;
      k = next;
    }

    const end = strip(data.slice(k, endpos));
    if (end !== '>' && end !== '/>') {
      this.delegate.handleData(data.slice(i, endpos));
      return endpos;
    }
    if (CDATA_CONTENT_ELEMENTS.has(tag)) this.setCdataMode(tag);
    const rawText = data.slice(i, endpos);
    if (end === '/>') this.delegate.handleStartendtag(tag, rawText);
    else this.delegate.handleStarttag(tag, rawText);
    return endpos;
  }

  // ------------------------------------------------------------------ end tag

  _parseEndTag(i) {
    const data = this.rawdata;
    const gt = data.indexOf('>', i + 1);
    if (gt === -1) return -1;
    let gtpos = gt + 1;

    // The strict form: '</', optional space, a name, optional space, '>'.
    const strict = this._matchEndTagFind(i);
    if (strict === null) {
      if (this.cdataElem !== null) {
        this.delegate.handleData(data.slice(i, gtpos));
        return gtpos;
      }
      let j = i + 2;
      if (!isAsciiLetterAt(data, j)) {
        if (matchesAt(data, i, '</>')) return i + 3;
        return this._parseBogusComment(i);
      }
      const nameStart = j;
      j += 1;
      while (isTagNameChar(data, j)) j++;
      const tagname = data.slice(nameStart, j).toLowerCase();
      while (isWs(data, j) || (data.charCodeAt(j) === 0x2f && data.charCodeAt(j + 1) !== 0x3e)) j++;
      gtpos = data.indexOf('>', j);
      this.delegate.handleEndtag(tagname, data.slice(i, gtpos + 1));
      return gtpos + 1;
    }

    const elem = strict.tag;
    if (this.cdataElem !== null && elem !== this.cdataElem) {
      this.delegate.handleData(data.slice(i, gtpos));
      return gtpos;
    }
    this.delegate.handleEndtag(elem, data.slice(i, strict.end));
    this.clearCdataMode();
    return strict.end;
  }

  /** `</\s*([a-zA-Z][-.a-zA-Z0-9:_]*)\s*>` anchored at `i`. */
  _matchEndTagFind(i) {
    const data = this.rawdata;
    if (!matchesAt(data, i, '</')) return null;
    let j = skipWs(data, i + 2);
    if (!isAsciiLetterAt(data, j)) return null;
    const nameStart = j;
    j += 1;
    while (j < data.length) {
      const code = data.charCodeAt(j);
      const ok =
        isAsciiLetterAt(data, j) ||
        (code >= 0x30 && code <= 0x39) ||
        code === 0x2d || code === 0x2e || code === 0x3a || code === 0x5f;
      if (!ok) break;
      j += 1;
    }
    const name = data.slice(nameStart, j);
    j = skipWs(data, j);
    if (data.charCodeAt(j) !== 0x3e) return null;
    return { tag: name.toLowerCase(), end: j + 1 };
  }

  // ------------------------------------------------- comments and declarations

  _parseComment(i) {
    const data = this.rawdata;
    // Closing sequence is '--' followed by optional whitespace and '>'.
    for (let j = i + 4; j < data.length; j++) {
      if (data.charCodeAt(j) !== 0x2d || data.charCodeAt(j + 1) !== 0x2d) continue;
      const k = skipWs(data, j + 2);
      if (data.charCodeAt(k) === 0x3e) {
        this.delegate.handleComment(data.slice(i + 4, j));
        return k + 1;
      }
    }
    return -1;
  }

  _parseBogusComment(i) {
    const data = this.rawdata;
    const pos = data.indexOf('>', i + 2);
    if (pos === -1) return -1;
    this.delegate.handleComment(data.slice(i + 2, pos));
    return pos + 1;
  }

  _parsePi(i) {
    const data = this.rawdata;
    const j = data.indexOf('>', i + 2);
    if (j === -1) return -1;
    this.delegate.handlePi(data.slice(i + 2, j));
    return j + 1;
  }

  _parseHtmlDeclaration(i) {
    const data = this.rawdata;
    if (matchesAt(data, i, '<!--')) return this._parseComment(i);
    if (matchesAt(data, i, '<![')) return this._parseMarkedSection(i);
    if (data.slice(i, i + 9).toLowerCase() === '<!doctype') {
      const gt = data.indexOf('>', i + 9);
      if (gt === -1) return -1;
      this.delegate.handleDecl(data.slice(i + 2, gt));
      return gt + 1;
    }
    return this._parseBogusComment(i);
  }

  _parseMarkedSection(i) {
    const data = this.rawdata;
    let j = i + 3;
    const nameStart = j;
    while (j < data.length && (isAsciiLetterAt(data, j) || isHexAt(data, j))) j++;
    const sectName = data.slice(nameStart, j).toLowerCase();
    if (['temp', 'cdata', 'ignore', 'include', 'rcdata'].includes(sectName)) {
      // Standard ']]>' terminator, allowing whitespace between the parts.
      for (let p = i + 3; p < data.length; p++) {
        if (data.charCodeAt(p) !== 0x5d) continue;
        let q = skipWs(data, p + 1);
        if (data.charCodeAt(q) !== 0x5d) continue;
        q = skipWs(data, q + 1);
        if (data.charCodeAt(q) !== 0x3e) continue;
        this.delegate.handleUnknownDecl(data.slice(i + 3, p));
        return q + 1;
      }
      return -1;
    }
    if (['if', 'else', 'endif'].includes(sectName)) {
      for (let p = i + 3; p < data.length; p++) {
        if (data.charCodeAt(p) !== 0x5d) continue;
        const q = skipWs(data, p + 1);
        if (data.charCodeAt(q) !== 0x3e) continue;
        this.delegate.handleUnknownDecl(data.slice(i + 3, p));
        return q + 1;
      }
      return -1;
    }
    return this._parseBogusComment(i);
  }
}

