/**
 * Pulls block-level raw HTML out of the document and replaces it with
 * placeholders, so the block parser never sees it and its contents are passed
 * through untouched.
 *
 * A run of raw HTML becomes "raw" when a block-level start tag appears at the
 * beginning of a line (up to three leading spaces are allowed); it ends when
 * the matching end tag closes the outermost element. Standalone constructs —
 * comments, processing instructions, declarations, marked sections and empty
 * tags such as `<hr>` — are stashed on their own when they start a line.
 */

import { isBlockLevel } from './util.mjs';
import { isBlank, isSpaceAt } from './chars.mjs';
import { HtmlTokenizer } from './htmltokenizer.mjs';

/** Tags that never have content and so never open a raw block by themselves. */
const EMPTY_TAGS = new Set(['hr']);

/** Matches two consecutive newlines, each optionally preceded by spaces. */
function startsWithBlankLine(text, from) {
  let i = from;
  while (text.charCodeAt(i) === 0x20) i++;
  if (text.charCodeAt(i) !== 0x0a) return false;
  i += 1;
  while (text.charCodeAt(i) === 0x20) i++;
  return text.charCodeAt(i) === 0x0a;
}

export class HtmlExtractor {
  constructor(stash) {
    this.stash = stash;
    this.inraw = false;
    this.intail = false;
    this.stack = [];
    this.cache = [];
    this.cleandoc = [];
    this.tokenizer = new HtmlTokenizer(this);
  }

  /** Extract raw HTML from `source`, returning the remaining document. */
  run(source) {
    this.tokenizer.parse(source);
    // Any unclosed raw block is stashed as-is.
    if (this.cache.length) {
      this.cleandoc.push(this.stash.store(this.cache.join('')));
      this.cache = [];
    }
    return this.cleandoc.join('');
  }

  /** True when the construct being reported starts a line. */
  atLineStart() {
    const offset = this.tokenizer.offset;
    if (offset === 0) return true;
    if (offset > 3) return false;
    const start = this.tokenizer.lineStart;
    return isBlank(this.tokenizer.rawdata.slice(start, start + offset));
  }

  /** Source text following the construct that is `length` characters long. */
  _textAfter(length) {
    return this.tokenizer.rawdata.slice(this.tokenizer.pos + length);
  }

  handleStarttag(tag, rawText) {
    if (EMPTY_TAGS.has(tag)) {
      this.handleStartendtag(tag, rawText);
      return;
    }
    if (isBlockLevel(tag) && (this.intail || (this.atLineStart() && !this.inraw))) {
      // A new raw block begins; keep it on a line of its own.
      this.inraw = true;
      this.cleandoc.push('\n');
    }
    if (this.inraw) {
      this.stack.push(tag);
      this.cache.push(rawText);
    } else {
      this.cleandoc.push(rawText);
      // A lone `<script>`/`<style>` outside a raw block (for instance inside a
      // code span) must not swallow the rest of the document.
      if (tag === 'script' || tag === 'style') this.tokenizer.clearCdataMode();
    }
  }

  handleEndtag(tag, rawText) {
    if (!this.inraw) {
      this.cleandoc.push(rawText);
      return;
    }
    this.cache.push(rawText);
    if (this.stack.includes(tag)) {
      while (this.stack.length) {
        if (this.stack.pop() === tag) break;
      }
    }
    if (this.stack.length === 0) {
      if (startsWithBlankLine(this.tokenizer.rawdata, this.tokenizer.pos + rawText.length)) {
        // Keep the blank line that closed the block.
        this.cache.push('\n');
      } else {
        this.intail = true;
      }
      this.inraw = false;
      this.cleandoc.push(this.stash.store(this.cache.join('')));
      this.cleandoc.push('\n\n');
      this.cache = [];
    }
  }

  handleData(data) {
    if (this.intail && data.indexOf('\n') !== -1) this.intail = false;
    if (this.inraw) this.cache.push(data);
    else this.cleandoc.push(data);
  }

  /** Handle a construct that has no separate end tag. */
  handleEmptyTag(data, isBlock) {
    if (this.inraw || this.intail) {
      this.cache.push(data);
      return;
    }
    if (this.atLineStart() && isBlock) {
      let text = data;
      if (startsWithBlankLine(this.tokenizer.rawdata, this.tokenizer.pos + data.length)) {
        text += '\n';
      } else {
        this.intail = true;
      }
      const last = this.cleandoc.length ? this.cleandoc[this.cleandoc.length - 1] : '';
      if (!last.endsWith('\n\n') && last.endsWith('\n')) this.cleandoc.push('\n');
      this.cleandoc.push(this.stash.store(text));
      this.cleandoc.push('\n\n');
      return;
    }
    this.handleData(data);
  }

  handleStartendtag(tag, rawText) {
    this.handleEmptyTag(rawText, isBlockLevel(tag));
  }

  handleCharref(name) {
    this.handleEmptyTag('&#' + name + ';', false);
  }

  handleEntityref(name) {
    this.handleEmptyTag('&' + name + ';', false);
  }

  handleComment(data) {
    this.handleEmptyTag('<!--' + data + '-->', true);
  }

  handleDecl(data) {
    this.handleEmptyTag('<!' + data + '>', true);
  }

  handlePi(data) {
    this.handleEmptyTag('<?' + data + '>', true);
  }

  handleUnknownDecl(data) {
    const end = data.startsWith('CDATA[') ? ']]>' : ']>';
    this.handleEmptyTag('<![' + data + end, true);
  }
}

/** Unused import guard: keeps the whitespace helper reachable for clarity. */
export const _isSpaceAt = isSpaceAt;

